    des.monster('kraken');
    des.monster('kraken');
    des.monster('kraken');
    des.monster('kraken');
    des.monster('kraken');
    des.monster('kraken');
    des.monster('shark');
    des.monster('shark');
    des.monster('shark');
    des.monster('shark');
    des.monster('piranha');
    des.monster('piranha');
    des.monster('piranha');
    des.monster('piranha');
    des.monster('jellyfish');
    des.monster('jellyfish');
    des.monster('jellyfish');
    des.monster('jellyfish');
    des.monster(';');
    des.monster(';');
    des.monster(';');
    des.monster(';');
    /* These guys feel like home here */
    des.monster({ id: 'water elemental', peaceful: 0 });
    des.monster({ id: 'water elemental', peaceful: 0 });
    des.monster({ id: 'water elemental', peaceful: 0 });
    des.monster({ id: 'water elemental', peaceful: 0 });
    des.monster({ id: 'water elemental', peaceful: 0 });
    des.monster({ id: 'water elemental', peaceful: 0 });
